/**
 * RelationDecision
 *
 * The relation, the IP and the other IP are all in the path
 * (`/review/ip-relations/{ip}/{relation}/{other_ip}/decision`). Simpler than RoleDecision: a
 * relation has no pairs of its own to bridge into (decision 0003, step 7). confirm: a relation
 * no rule suggested may be confirmed too (asserted). reject: nothing else.
 */
export type RelationDecision = {
    /**
     * Decision
     */
    decision: 'confirm' | 'reject';
    /**
     * Note
     *
     * the reviewer's reasoning; kept on the row
     */
    note?: string;
};

/**
 * RelationDecisionResult
 */
export type RelationDecisionResult = {
    /**
     * Ip
     */
    ip: string;
    /**
     * Relation
     */
    relation: string;
    /**
     * Other Ip
     */
    other_ip: string;
    /**
     * Vantage
     */
    vantage: string;
    /**
     * Decision
     */
    decision: string;
    /**
     * Asserted
     *
     * confirm: true when no rule had suggested this relation, so the row was created by the decision
     */
    asserted?: boolean;
    /**
     * Rollups
     */
    rollups?: string;
};

/**
 * ReviewQueue
 *
 * Suggested counts by queue: the Overview tile and the Candidate review
 * chips. Pairs are not a queue: a pair is confirmed as a consequence of
 * confirming an IP's role, and an unconfirmed pair is evidence under that
 * role, not a decision of its own (user, 2026-10-16). Since 0089 a row is
 * an (ip, role), so these count suggested roles, not IPs.
 */
export type ReviewQueue = {
    /**
     * Asn Candidates
     */
    asn_candidates: number;
    /**
     * Peer Roles
     */
    peer_roles: number;
    /**
     * Watched Roles
     */
    watched_roles: number;
    /**
     * Peer Relations
     *
     * suggested relations (operator, c2_victim, c2_operator, research, peer-vantage sip_trunk/sip_client -- stabilization step 7); every relation today is peer vantage
     */
    peer_relations?: number;
    /**
     * Confirmed In Doubt
     *
     * confirmed roles the 30-day re-check flagged: the agent now disagrees, or no rule has seen it for 30 days; the role stands until you change it
     */
    confirmed_in_doubt?: number;
};

/**
 * RoleChoiceIn
 *
 * One entry of RoleDecisions: a role of the IP in the path and what to decide about it.
 */
export type RoleChoiceIn = {
    /**
     * Role
     */
    role: string;
    /**
     * Decision
     */
    decision: 'confirm' | 'reject';
    /**
     * Note
     *
     * this role's own reasoning; replaces the request's note for this role when not empty
     */
    note?: string | null;
};

/**
 * RoleChoiceResult
 */
export type RoleChoiceResult = {
    /**
     * Role
     */
    role: string;
    /**
     * Decision
     */
    decision: string;
    /**
     * Asserted
     *
     * confirm: true when no rule had suggested this role, so the row was created by the decision
     */
    asserted?: boolean;
    /**
     * Pairs
     *
     * confirm: the relationships confirmed
     */
    pairs?: Array<ConfirmedPair>;
    /**
     * Pairs Unconfirmed
     *
     * reject: how many confirmed pairs were cleared
     */
    pairs_unconfirmed?: number | null;
};

/**
 * RoleDecision
 *
 * The role is in the path (`/review/ip-roles/{ip}/{role}/decision`).
 * confirm: optionally the exact `pairs` to confirm for a SIP role
 * (default: every measured pair whose measured role matches); a role no
 * rule suggested may be confirmed too (asserted). reject: nothing else.
 */
export type RoleDecision = {
    /**
     * Decision
     */
    decision: 'confirm' | 'reject';
    /**
     * Pairs
     */
    pairs?: Array<PairRef> | null;
    /**
     * Note
     *
     * the reviewer's reasoning; kept on the row and in the pairs' source stamp; required (not empty) when the confirm asserts a role, that is when no row exists for it
     */
    note?: string;
};

/**
 * RoleDecisionResult
 */
export type RoleDecisionResult = {
    /**
     * Ip
     */
    ip: string;
    /**
     * Role
     */
    role: string;
    /**
     * Vantage
     */
    vantage: string;
    /**
     * Decision
     */
    decision: string;
    /**
     * Asserted
     *
     * confirm: true when no rule had suggested this role, so the row was created by the decision
     */
    asserted?: boolean;
    /**
     * Pairs
     *
     * confirm: the relationships confirmed
     */
    pairs?: Array<ConfirmedPair>;
    /**
     * Pairs Unconfirmed
     *
     * reject: how many confirmed pairs were cleared
     */
    pairs_unconfirmed?: number | null;
    /**
     * Rollups
     */
    rollups?: string;
};

/**
 * RoleDecisions
 *
 * `/review/ip-roles/{ip}/decisions`: several roles of one IP decided in one request, all or
 * nothing. No `pairs`: a SIP confirm takes the single route's default. The list may be empty
 * here so the writer refuses it in its own words (422).
 */
export type RoleDecisions = {
    /**
     * Decisions
     */
    decisions: Array<RoleChoiceIn>;
    /**
     * Note
     *
     * the reviewer's reasoning, kept on every row and history entry the request touches; an entry's own note replaces it for that row; an entry that asserts a role (no row yet) needs one or the other
     */
    note?: string;
};

/**
 * RoleDecisionsResult
 */
export type RoleDecisionsResult = {
    /**
     * Ip
     */
    ip: string;
    /**
     * Vantage
     */
    vantage: string;
    /**
     * Action Id
     *
     * the uuid every history entry of this request carries
     */
    action_id: string;
    /**
     * Results
     *
     * one per entry, in the request's order
     */
    results: Array<RoleChoiceResult>;
    /**
     * Rollups
     */
    rollups?: string;
};

/**
 * RoleDoc
 */
export type RoleDoc = {
    /**
     * Name
     */
    name: string;
    /**
     * Meaning
     */
    meaning: string;
    /**
     * Kind
     *
     * role (a statement about the box alone) or relation (relative to another IP; decision 0003)
     */
    kind: string;
    /**
     * whether an analyst may assert this role (confirm it where no row exists) on a watched or a peer IP; false on both for a relation-only name
     */
    assertable: Assertable;
    /**
     * Retired
     *
     * true once a role is retired: no longer assertable anew (none is marked yet)
     */
    retired?: boolean;
};

/**
 * RoleHistoryEntry
 *
 * One entry of the decision history of a role (decision 0003): what happened, the status
 * the role row had once it was written, and who or what did it. Oldest first. `seeded` marks
 * entries rebuilt at migration 0107 from the rows' last values; earlier history was overwritten.
 */
export type RoleHistoryEntry = {
    /**
     * Id
     */
    id: number;
    /**
     * Subject Kind
     *
     * role today; relation from step 6 of the stabilization
     */
    subject_kind: string;
    /**
     * Ip
     */
    ip: string;
    /**
     * Name
     *
     * the role
     */
    name: string;
    /**
     * Other Ip
     *
     * the other IP of a relation; null for a role
     */
    other_ip: string | null;
    /**
     * Decision
     *
     * suggested | revived | withdrawn (a rule), evaluated | reopened | kept | holds | doubted (the model), confirmed | asserted | rejected (the analyst), expired (retired expiry, seeded only)
     */
    decision: string;
    /**
     * Status After
     *
     * the row's status once the entry is written; null when the row was deleted (withdrawn)
     */
    status_after: string | null;
    /**
     * Decided By
     *
     * the path (api, review-ip-roles skill), rule:<name>, or model:<id>; legacy stamps verbatim when seeded
     */
    decided_by: string;
    /**
     * Note
     */
    note: string;
    /**
     * Evaluation
     *
     * the model's verdict, reasoning and model for its entries
     */
    evaluation: {
        [key: string]: unknown;
    } | null;
    /**
     * Seeded
     */
    seeded: boolean;
    /**
     * At
     */
    at: string;
    /**
     * Action Id
     *
     * one uuid shared by every entry one POST /review/ip-roles/{ip}/decisions request wrote; null for every other entry (and for every relation entry for now)
     */
    action_id?: string | null;
    /**
     * Replaced By
     *
     * on a rejected entry that has an action_id: the roles the same request confirmed or asserted, oldest first (an empty list when it only rejected); null on every other entry
     */
    replaced_by?: Array<string> | null;
};

