    /**
     * Rtp Days
     */
    rtp_days: number | null;
    /**
     * Sip Packets
     */
    sip_packets: number | null;
    /**
     * Sip Per Day From Peer
     */
    sip_per_day_from_peer: number | null;
    /**
     * Sip Src Ports
     */
    sip_src_ports: number | null;
